{
  "technical_and_design_decisions": [
    "Extend channel configuration Protobuf definitions and Go packages (fabric/common/channelconfig and fabric/common/capabilities) to support Channel, Application, and Orderer capability maps.",
    "Implement binary failure/crash behavior during channel config parsing when an unsupported capability string is encountered.",
    "Enforce orderer group capability checks prior to allowing application group capabilities activation.",
    "Implement an uncommitted transaction write-set buffer in the Go chaincode shim to support Read-Your-Writes (RYW) key retrieval via GetTrxState API.",
    "Refactor chaincode subsystem singletons to struct instances initialized via dependency injection during peer startup.",
    "Decouple MSPConfig creation from configtxgen tool by converting MSPConfig to an interface.",
    "Implement validation parameters interface in the new chaincode lifecycle package, returning an automatically generated majority-of-orgs endorsement policy for +lifecycle."
  ],
  "assumptions": [
    "Development work will be performed in Go within the Hyperledger Fabric core repository.",
    "CouchDB benchmarking will utilize standardized query patterns and automated benchmark scripts (e.g., Caliper or custom integration test suites).",
    "Video creation for adding organizations will include slide creation, screen recording, editing, and technical documentation.",
    "Integration tests will run using standard Docker-based integration test environments."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Capabilities Framework Implementation",
      "activity_description": "Implement Protobuf updates, channelconfig API extensions, capability maps for Channel, Application, and Orderer, V1.1 capability flags, and binary enforcement/crash behavior.",
      "most_likely_effort": 60
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Chaincode Read-Your-Writes (RYW) API Extension",
      "activity_description": "Extend chaincode stub interface and transaction simulator buffer to support RYW during transaction execution, implementing GetTrxState.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Dynamic Org Addition Video & Tutorial Guide",
      "activity_description": "Create presentation graphics, step-by-step script, record, and produce tutorial video showing runtime addition of organizations without network downtime.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "CouchDB Query Performance Benchmarking",
      "activity_description": "Design query performance tests for CouchDB state database, run benchmarks across varying state sizes, and document query performance metrics.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "MSPConfig Interface Refactoring",
      "activity_description": "Refactor MSPConfig into an interface to support programmatic channel config block construction outside of configtxgen.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Chaincode Subsystem Singleton Removal",
      "activity_description": "Refactor global singletons in the chaincode subsystem into injectable dependencies to improve testability and prepare for new lifecycle implementation.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Integration Test World Config YAML Generator",
      "activity_description": "Enhance test integration framework to generate core.yaml and orderer.yaml dynamically based on World configuration settings.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Lifecycle Validation Parameters & Default Policies",
      "activity_description": "Implement validation parameters interface for the new chaincode lifecycle and add default endorsement policy generation (majority orgs) for +lifecycle.",
      "most_likely_effort": 28
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "End-to-End Integration Testing and Documentation",
      "activity_description": "Perform regression testing, end-to-end integration tests across capabilities and lifecycle components, and update developer documentation.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 232
  }
}
```

